'use client'

import { CircleOff } from 'lucide-react'
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from './empty'
import { ReactNode, cloneElement, isValidElement } from 'react'

const ForbiddenPage = () => (
  <Empty>
    <EmptyHeader>
      <EmptyMedia>
        <CircleOff className="text-muted-foreground" />
      </EmptyMedia>
      <EmptyTitle>403 - Prohibido</EmptyTitle>
      <EmptyDescription>
        No tienes permisos suficientes para acceder.
      </EmptyDescription>
    </EmptyHeader>
  </Empty>
)

export const ForbiddenDisabled = ({ children }: { children?: ReactNode }) => {
  if (!children) return null
  if (!isValidElement(children)) return null

  return cloneElement<any>(children, {
    disabled: true,
    onClick: undefined,
    onChange: undefined,
    'aria-disabled': true,
    tabIndex: -1,
  })
}

export type ForbiddenProps = {
  variant?: 'page' | 'disabled'
  children?: ReactNode
}

export default function Forbidden({
  variant = 'page',
  children,
}: ForbiddenProps) {
  return (
    <>
      {variant === 'page' && <ForbiddenPage />}
      {variant === 'disabled' && (
        <ForbiddenDisabled>{children}</ForbiddenDisabled>
      )}
    </>
  )
}

'use client'

import usePerms from '@/hooks/auth/use-perms'
import Forbidden, { ForbiddenProps } from './forbidden'
import { useProfileContext } from '@/providers/profile-provider'
import { Spinner } from './spinner'

type CanAccessProps = {
  subdomain: string
  resource: string
  action: string
} & ForbiddenProps

export default function CanAccess({
  subdomain,
  resource,
  action,
  variant,
  children,
}: CanAccessProps) {
  const { canAccess } = usePerms()
  const { isLoading } = useProfileContext()
  const hasAccess = canAccess(subdomain, resource, action)

  if (isLoading)
    return (
      <div className="flex items-center justify-center">
        <Spinner />
      </div>
    )

  if (hasAccess) return children
  return <Forbidden variant={variant}>{children}</Forbidden>
}

'use client'
import { useProfileContext } from '@/providers/profile-provider'

/**
 * Hook para gestionar la verificación de permisos por aplicación.
 */
export default function usePerms() {
  const { profile } = useProfileContext()

  /**
   * Verifica si el usuario tiene acceso a una acción específica sobre un recurso en un subdominio.
   */
  const canAccess = (subdomain: string, resource: string, action: string) => {
    if (profile?.is_superuser) return true

    const appPerm = profile?.roles
      ?.flatMap((role) => role?.app_perms || [])
      ?.find((item) => item?.subdomain === subdomain)
    return (appPerm as any)?.[resource]?.[action] === true
  }

  /**
   * Verifica si la aplicación debe mostrarse (si el usuario tiene algún permiso en ella).
   */
  const showApp = (subdomain: string) => {
    if (profile?.is_superuser) return true

    return profile?.roles
      ?.flatMap((role) => role?.app_perms || [])
      ?.some((item) => item?.subdomain === subdomain)
  }

  return {
    canAccess,
    showApp,
  }
}

'use client'

import { Suspense, createContext, useContext } from 'react'
import useProfile from '@/hooks/auth/use-profile'
import { Spinner } from '@/components/ui/spinner'

type UseProfileReturn = ReturnType<typeof useProfile>
type ProfileData = UseProfileReturn['data']

type ProfileContextType = {
  profile: ProfileData | undefined
  isLoading: boolean
  error: Error | null
  refetch: () => void
}

export const ProfileContext = createContext<ProfileContextType>({
  profile: undefined,
  isLoading: true,
  error: null,
  refetch: () => {},
})

export const useProfileContext = () => {
  const context = useContext(ProfileContext)
  if (!context) {
    throw new Error('useProfileContext must be used within a ProfileProvider')
  }
  return context
}

export default function ProfileProvider({
  children,
}: {
  children: React.ReactNode
}) {
  const { data: profile, isLoading, error, refetch } = useProfile()

  return (
    <ProfileContext.Provider
      value={{
        profile,
        isLoading,
        error: error as Error | null,
        refetch,
      }}
    >
      <Suspense
        fallback={
          <div className="flex justify-center items-center h-screen">
            <Spinner />
          </div>
        }
      >
        {children}
      </Suspense>
    </ProfileContext.Provider>
  )
}

'use client'

import { supabase } from '@/lib/supabase/client'
import { Tables } from '@/types/supabase.types'
import { useQuery } from '@tanstack/react-query'
import useUser from './use-user'

type UserView = Tables<'users_view'> & {
  roles: {
    name: Tables<'roles'>['name']
    description?: Tables<'roles'>['description']
    app_perms?: Tables<'role_app_perms'> &
      {
        app_id: Tables<'apps'>['id']
        subdomain: Tables<'apps'>['subdomain']
        perms: Tables<'role_app_perms'>['perms']
      }[]
  }[]
}

export default function useProfile() {
  const { data: user } = useUser()
  const query = useQuery({
    queryKey: ['profile'],
    queryFn: async (): Promise<UserView> => {
      if (!user?.id) {
        throw new Error('User not found')
      }
      const { data, error } = await supabase
        .from('users_view')
        .select('*')
        .eq('id', user?.id)
        .single()

      if (error) throw error

      return data as UserView
    },
  })
  return query
}

'use client'

import { supabase } from '@/lib/supabase/client'
import { useQuery } from '@tanstack/react-query'

export default function useUser() {
  const userQuery = useQuery({
    queryKey: ['user'],
    queryFn: async () => {
      const { data } = await supabase.auth.getSession()
      return data.session?.user
    },
  })

  return userQuery
}
